package co.edu.uco.seguridad.pdp.authorization.application.usecase.impl;
import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.ListApplicationProfileAssignmentsRequest; import co.edu.uco.seguridad.pdp.authorization.application.rule.validator.PrincipalMustBeApplicationAdministratorValidator; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ListApplicationProfileAssignmentsUseCase; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.ProfileAssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationProfileAssignmentsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import reactor.core.publisher.Mono;
public final class ListApplicationProfileAssignmentsUseCaseImpl implements ListApplicationProfileAssignmentsUseCase {private final PrincipalMustBeApplicationAdministratorValidator gate;private final ListApplicationProfileAssignmentsPageUseCase assignments;public ListApplicationProfileAssignmentsUseCaseImpl(PrincipalMustBeApplicationAdministratorValidator gate,ListApplicationProfileAssignmentsPageUseCase assignments){this.gate=gate;this.assignments=assignments;}public Mono<ResultPage<ProfileAssignmentResponse>> execute(ListApplicationProfileAssignmentsRequest i){return gate.execute(i.administration()).then(Mono.defer(()->assignments.execute(new ListApplicationAssignmentsPageRequest(i.administration().tenantId(),i.administration().applicationId(),i.window()))));}}
